insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-116', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'A 0.050 M solution in a cell of constant $1.20\ \mathrm{cm^{-1}}$ has $R = 50\ \Omega$. $\Lambda_m$ of the solute is', '["$480\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$24\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$0.48\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$1200\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$"]'::jsonb, 0, '$\kappa = (1/50)\times 1.20 = 0.024\ \mathrm{S\ cm^{-1}}$; then $\Lambda_m = 1000\times 0.024/0.050 = 480\ \mathrm{S\ cm^2\ mol^{-1}}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'conductance') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
