insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-118', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'For a 1:1 salt MX the limiting molar conductivity may be written', '["$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+) + \\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+)/\\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+) - \\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = 2\\lambda^\\circ(\\mathrm{M}^+)$ always"]'::jsonb, 0, 'One mole of MX yields one mole of each ion, so the ionic contributions simply add.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'kohlrausch') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
